import {useEffect,useMemo,useRef,useState,type ReactNode} from 'react';
import {AnimatePresence,motion} from 'framer-motion';
import * as Dialog from '@radix-ui/react-dialog';
import {Area,AreaChart,Bar,BarChart,CartesianGrid,Legend,ReferenceLine,ResponsiveContainer,Tooltip,XAxis,YAxis} from 'recharts';
import {ArrowDownToLine,ArrowRight,ArrowUpRight,Bell,Blocks,Box,BrainCircuit,CalendarDays,Check,CheckCheck,CheckCircle2,ChevronRight,ChevronsUpDown,CircleHelp,ClipboardCheck,Clock3,Database,Factory,FileText,FlaskConical,History,LayoutDashboard,Link2,MessageSquare,Network,Package,Pause,Pencil,Play,RefreshCw,RotateCcw,Search,Settings2,ShieldCheck,ShoppingCart,SkipForward,Sparkles,Truck,Wallet,X,Zap,AlertTriangle} from 'lucide-react';
import {Button} from '../components/ui/button';
import {addDays,BASE,createSeed,scenarios,sourceNotes,type ErpData,type Scenario,type TableKind} from './model';
import {analyze,approvalErrors,createOrder,demand,executeStage,fingerprint,fmt,lotReview,shortDate,stages,won,type Evidence,type Option,type PurchaseOrder,type Report} from './calculator';
import {DataGrid,exportRows,type Column,type Row} from './DataGrid';
