import './erp.css';
import './enterprise.css';
type Page='dashboard'|'workspace'|'recommendation'|'inventory'|'suppliers'|'production'|'orders'|'settings';
const nav=[{id:'dashboard',label:'업무 대시보드',icon:LayoutDashboard},{id:'workspace',label:'AI 분석 Workspace',icon:Network},{id:'recommendation',label:'발주 검토 · 추천서',icon:ClipboardCheck},{id:'inventory',label:'원료 · Lot 재고',icon:Box},{id:'suppliers',label:'견적 · 공급 확약',icon:Truck},{id:'production',label:'생산 · 입고 계획',icon:Factory},{id:'orders',label:'발주 · 변경 이력',icon:FileText}] as const;
const agents=[{name:'구매 AI',role:'단가·MOQ·공급 확약',icon:ShoppingCart,color:'#4d75cb'},{name:'재고·물류 AI',role:'Lot·유효기간·가용량',icon:Package,color:'#328f8b'},{name:'생산관리 AI',role:'투입일·부족량',icon:Factory,color:'#8d6ac2'},{name:'QC/QA AI',role:'시험·사용 승인',icon:ShieldCheck,color:'#bb944e'},{name:'재무 AI',role:'총비용·예산·현금',icon:Wallet,color:'#b06b91'},{name:'Admin AI',role:'근거 검증·최종 조율',icon:BrainCircuit,color:'#315b92'}];
function Tag({children,tone='neutral'}:{children:ReactNode;tone?:string}){return <span className={'badge '+tone}>{children}</span>}
function Panel({children,className=''}:{children:ReactNode;className?:string}){return <section className={'panel '+className}>{children}</section>}
function Modal({title,open,onClose,children,wide=false}:{title:string;open:boolean;onClose:()=>void;children:ReactNode;wide?:boolean}){return <Dialog.Root open={open} onOpenChange={v=>!v&&onClose()}><Dialog.Portal><Dialog.Overlay className="modal-overlay"/><Dialog.Content className={'modal erp-modal '+(wide?'wide':'')}><div className="modal-heading"><Dialog.Title>{title}</Dialog.Title><Dialog.Close className="icon-button" aria-label="닫기"><X size={18}/></Dialog.Close></div><Dialog.Description className="sr-only">{title}의 데이터와 근거를 확인합니다.</Dialog.Description><div className="modal-body">{children}</div></Dialog.Content></Dialog.Portal></Dialog.Root>}
interface Editing {type:TableKind|'config';id:string;values:Record<string,string>;}
const editLabels:Record<string,string>={quantity:'수량 (바이알)',expiry:'유효일',unitPrice:'단가 (원/바이알)',moq:'MOQ (바이알)',multiple:'주문배수 (바이알)',shipping:'회당 운송비 (원)',quoteExpiry:'견적 유효일',date:'생산 투입일',il7:'IL-7 필요량',il15:'IL-15 필요량',arrival:'입고 처리 완료일',qcDelay:'QC 시작 대기 (일)',payment:'지급일',cashLimit:'지급일 현금 한도 (원)',budget:'구매예산 한도 (원)',qcDays:'QC 시험 기간 (일)',qaDays:'QA 검토 기간 (일)',testingPerLot:'입고 Lot별 시험비 (원)',storagePerVialDay:'바이알·일 보관비 (원)',disposalPerVial:'바이알당 폐기처리비 (원)'};
const dateFields=new Set(['expiry','quoteExpiry','date','arrival','payment']);
export default function ErpApp({onLegacy}:{onLegacy:()=>void}){
 const [initial]=useState(load);const [data,setData]=useState(initial.data);const [orders,setOrders]=useState(initial.orders);const [reports,setReports]=useState(initial.reports);const [report,setReport]=useState<Report|null>(initial.reports[0]||null);
 const [page,setPage]=useState<Page>('dashboard');const [table,setTable]=useState<TableKind>('lots');const [candidate,setCandidate]=useState('B');
 const [events,setEvents]=useState<Evidence[]>([]);const [running,setRunning]=useState(false);const [started,setStarted]=useState(false);const [intervalMs,setIntervalMs]=useState(1800);const [selectedEvent,setSelectedEvent]=useState<Evidence|null>(null);const [inspectedEvent,setInspectedEvent]=useState<Evidence|null>(null);
 const [selectedRow,setSelectedRow]=useState<{row:Row;column:string;table:TableKind}|null>(null);const [editing,setEditing]=useState<Editing|null>(null);const [editError,setEditError]=useState('');
 const [modal,setModal]=useState<'scenario'|'approve'|'source'|'reset'|'history'|'help'|null>(null);const [toast,setToast]=useState('');const [question,setQuestion]=useState('');const [answer,setAnswer]=useState('');const logRef=useRef<HTMLDivElement>(null);
 const analysis=useMemo(()=>analyze(data),[data]);const verdicts=useMemo(()=>departmentVerdicts(data,analysis),[data,analysis]);const firstPriceVendor=[...data.vendors].filter(v=>v.confirmed&&v.approved&&v.productApproved).sort((a,b)=>a.unitPrice-b.unitPrice)[0];const initialOption=analysis.options.find(o=>o.id===firstPriceVendor?.id);const stale=!!report&&(report.fingerprint!==fingerprint(data)||report.revision!==data.revision);const liveOption=analysis.options.find(o=>o.id===candidate)!;
 const done=started&&events.length===stages.length;const latest=selectedEvent||(events.length?events[events.length-1]:null);const inProgress=running?stages[Math.min(events.length,stages.length-1)]:null;const rowHighlights=latest?.revision===data.revision&&latest.table===table?latest.rows:[];const colHighlights=latest?.revision===data.revision&&latest.table===table?latest.columns:[];
 const currentOrders=useMemo(()=>reviewOrders(orders,data),[orders,data]);const approvalProblems=report?approvalErrors(data,report,currentOrders):['분석을 먼저 완료하세요.'];
 useEffect(()=>{if(!save({data,orders,reports}))setToast('브라우저 저장 공간이 부족합니다. 현재 세션에서는 계속 사용할 수 있습니다.')},[data,orders,reports]);
 useEffect(()=>{if(!toast)return;const t=setTimeout(()=>setToast(''),4200);return()=>clearTimeout(t)},[toast]);
 useEffect(()=>{if(logRef.current)logRef.current.scrollTop=logRef.current.scrollHeight},[events]);
 function finalize(d:ErpData,list:Evidence[]){const r:Report={id:`ANA-R${d.revision}-${Date.now()}`,revision:d.revision,fingerprint:fingerprint(d),createdAt:new Date().toISOString(),analysis:analyze(d),events:structuredClone(list),data:structuredClone(d)};setReport(r);setReports(prev=>[r,...prev].slice(0,10));setRunning(false);setToast(r.analysis.selected?`분석 완료 · ${r.analysis.selected}안의 근거와 조건을 확인하세요.`:'분석 완료 · 적격 후보 없음. 생산·품질·예산 조치가 필요합니다.');}
 useEffect(()=>{if(!running||events.length>=stages.length)return;const t=setTimeout(()=>{const ev=executeStage(data,events.length);const next=[...events,ev];setEvents(next);setTable(ev.table);setSelectedEvent(null);if(next.length===stages.length)finalize(data,next);},stagePlaybackMs(data,events.length,intervalMs));return()=>clearTimeout(t)},[running,events,data,intervalMs]);
 function go(p:Page){setPage(p);if(p==='inventory')setTable('lots');if(p==='suppliers')setTable('quotes');if(p==='production')setTable('production');setSelectedRow(null);window.scrollTo({top:0,behavior:'smooth'})}
 function start(){setPage('workspace');setTable('lots');setEvents([]);setSelectedEvent(null);setStarted(true);setRunning(true);setAnswer('');}
 function skip(){const list=[...events];for(let i=list.length;i<stages.length;i++)list.push(executeStage(data,i));setEvents(list);setTable('costs');setSelectedEvent(null);setStarted(true);finalize(data,list)}
 function commit(next:ErpData,entity:string,field:string,before:string,after:string){try{const d=revise(data,next,entity,field,before,after);setData(d);setRunning(false);setStarted(false);setEvents([]);setSelectedEvent(null);setSelectedRow(null);setToast(`R${d.revision} 저장 · 연결된 계산을 갱신했습니다. 기존 추천·PO는 재검증이 필요합니다.`);return true}catch(e){setEditError((e as Error).message);return false}}
 function changeScenario(id:Scenario){const next=scenarioData(data,id);setData(next);setRunning(false);setStarted(false);setEvents([]);setSelectedEvent(null);setModal(null);setPage('workspace');setTable(id==='qc-delay'||id==='temperature'||id==='quality-scope'?'shipments':id==='production-delay'?'production':'lots');setToast(`${scenarios.find(s=>s.id===id)!.name} · 기준 데이터에서 독립 적용했습니다. 재분석을 시작하세요.`)}
 function inspect(ev:Evidence){setTable(ev.table);setSelectedEvent(ev);setInspectedEvent(ev)}
 function beginEdit(kind:TableKind|'config',row:Row){let source:Record<string,unknown>={},keys:string[]=[];
 if(kind==='lots'){source={...data.lots.find(l=>l.id===row.id)!};keys=['quantity','expiry'];}
 if(kind==='quotes'){source={...data.vendors.find(v=>v.id===row.id)!};keys=['unitPrice','moq','multiple','shipping','quoteExpiry'];}
 if(kind==='production'){source={...data.productions.find(p=>p.id===row.id)!};keys=['date','il7','il15'];}
 if(kind==='shipments'){source={...data.vendors.flatMap(v=>v.shipments).find(s=>s.id===row.id)!};keys=['quantity','arrival','qcDelay','expiry','payment','cashLimit'];}
 if(kind==='config'){source={...data.config};keys=['budget','qcDays','qaDays','testingPerLot','storagePerVialDay','disposalPerVial'];}
 setEditing({type:kind,id:row.id,values:Object.fromEntries(keys.map(k=>[k,String(source[k])]))});setEditError('');}
 function submitEdit(){if(!editing)return;const next=structuredClone(data);const changes:Record<string,string|number>={};for(const [k,v] of Object.entries(editing.values)){if(!v.trim()){setEditError('모든 입력값을 채워주세요.');return}changes[k]=dateFields.has(k)?v:Number(v)}
 if(editing.type==='lots')Object.assign(next.lots.find(l=>l.id===editing.id)!,changes);
 if(editing.type==='quotes')Object.assign(next.vendors.find(v=>v.id===editing.id)!,changes);
 if(editing.type==='production'){const p=next.productions.find(p=>p.id===editing.id)!;Object.assign(p,changes);if(p.date!==data.productions.find(x=>x.id===p.id)!.date){p.completion=addDays(p.date,5);p.delivery=addDays(p.date,8)}}
 if(editing.type==='shipments')Object.assign(next.vendors.flatMap(v=>v.shipments).find(s=>s.id===editing.id)!,changes);
 if(editing.type==='config')Object.assign(next.config,changes);
 if(commit(next,editing.id,Object.keys(changes).join(', '),'편집 전 R'+data.revision,JSON.stringify(changes)))setEditing(null);}
 function approve(){if(!report)return;try{const order=createOrder(data,report,currentOrders);setOrders(prev=>[order,...prev]);setModal(null);setToast(`${order.id} 등록 · 미래 QC/QA는 예측 상태이며 현재 재고·품질 승인은 변경하지 않았습니다.`)}catch(e){setToast((e as Error).message);setModal(null)}}
 function ask(q:string){setQuestion(q);const a=analysis,A=a.options[0],B=a.options[1],C=a.options[2];setAnswer(q.includes('비용')||q.includes('저렴')||q.includes('단가')?`A 단가 ${won(data.vendors[0].unitPrice)} / B 단가 ${won(data.vendors[1].unitPrice)}이지만, MOQ 반영 수량은 A ${A.quantity}개 / B ${B.quantity}개입니다. 구매·운송 소계 차이는 ${won(A.subtotal-B.subtotal)}이며, 시험·보관·폐기처리 포함 총비용 차이는 ${won(A.total-B.total)}입니다. A 예상 폐기 ${A.waste}개도 별도로 확인해야 합니다. ${B.eligible?'B가 필수조건을 충족합니다.':`현재 B는 ${B.constraints.join(', ')}로 승인할 수 없습니다.`}`:q.includes('QC')||q.includes('지연')?`${B.deliveries.map(s=>`${s.id}: ${s.arrival} + 대기 ${s.qcDelay}일 + QC ${data.config.qcDays}일 + QA ${data.config.qaDays}일 = ${s.available}`).join('; ')}. ${B.shortage?`생산 부족 ${B.shortage}개. ${a.actions.join(' ')}`:'예측상 각 생산 투입을 충족합니다. 실제 사용 승인은 별도입니다.'}`:q.includes('C')?`C는 업체·제품 ${C.qualityApproved?'승인':'미승인'}과 공급 ${C.confirmed?'확약':'미확약'}을 별도로 판정합니다. 제외/보류 사유: ${C.constraints.join(', ')||'없음'}. 미확약 물량은 생산 가용 재고에 포함하지 않습니다.`:`장부 ${a.need.ledger}개 중 품질·유효기간을 통과한 생산 가용량은 ${a.need.stock}개입니다. ${lotReview(data).filter(l=>!l.usable).map(l=>`${l.id}: ${l.reason}`).join('; ')}. 신규 수요는 ${a.need.total} + ${a.need.safety} − ${a.need.stock} = ${a.need.required}개입니다. 품질 보류를 AI가 임의 승인하지 않으며 IL-15는 별도 원료입니다.`)}
 function revisionVariant(){const d=structuredClone(data);d.productions[1].il7+=1;commit(d,'PROD-02','IL-7 수요',String(data.productions[1].il7),String(d.productions[1].il7));}
 const heading=(eyebrow:string,title:string,desc:string,actions?:ReactNode)=><div className="page-heading"><div><div className="eyebrow">{eyebrow}</div><h1>{title}</h1><p>{desc}</p></div><div className="heading-actions">{actions}</div></div>;
 const phase=stages[Math.min(events.length,stages.length-1)];
 const grid=(kind:TableKind,highlight=false)=><DataGrid key={kind} title={tableLabels[kind]} rows={getRows(data,analysis,kind,candidate)} columns={columns[kind]} revision={data.revision} highlightRows={highlight?rowHighlights:[]} highlightCols={highlight?colHighlights:[]} onSelect={(row,column)=>{setSelectedRow({row,column,table:kind});if((kind==='quotes'||kind==='costs')&&['A','B','C'].includes(row.id))setCandidate(row.id)}} onEdit={kind==='costs'?undefined:row=>beginEdit(kind,row)} selectedId={selectedRow?.table===kind?selectedRow.row.id:undefined} onExport={setToast}/>;
 const tableTabs=<div className="erp-data-tabs">{(Object.keys(tableLabels) as TableKind[]).map(k=><button key={k} onClick={()=>{setTable(k);setSelectedRow(null)}} className={table===k?'active':''}>{tableLabels[k]}</button>)}</div>;
 const chart=(o:Option=liveOption)=><div className="erp-stock-chart"><ResponsiveContainer width="100%" height="100%"><AreaChart data={o.points} margin={{left:-25,right:12,top:12,bottom:0}}><defs><linearGradient id="erp-stock-fill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#6085d5" stopOpacity={.2}/><stop offset="100%" stopColor="#6085d5" stopOpacity={0}/></linearGradient></defs><CartesianGrid strokeDasharray="3 5" vertical={false} stroke="#edf1f6"/><XAxis dataKey="date" tickFormatter={shortDate} tick={{fontSize:13,fill:'#8a9bb2'}} axisLine={false} tickLine={false}/><YAxis allowDecimals={false} tick={{fontSize:13,fill:'#8a9bb2'}} axisLine={false} tickLine={false}/><Tooltip formatter={(v)=>[`${v}바이알`,'예측 가용']} labelFormatter={v=>String(v)} contentStyle={{fontSize:15,borderRadius:8,border:'1px solid #e3eaf5'}}/><ReferenceLine y={analysis.need.safety} stroke="#c49c61" strokeDasharray="4 4" label={{value:'안전 '+analysis.need.safety,position:'insideTopRight',fontSize:12,fill:'#b59a74'}}/>{selectedRow?.table==='production'&&!!selectedRow.row.date&&<ReferenceLine x={String(selectedRow.row.date)} stroke="#8ba7d4" strokeDasharray="3 3" label={{value:String(selectedRow.row.id),fontSize:12,fill:'#7e9bc2'}}/>}<Area type="stepAfter" dataKey="stock" stroke="#6485cb" fill="url(#erp-stock-fill)" strokeWidth={2} isAnimationActive={false}/></AreaChart></ResponsiveContainer></div>;
 const metrics=<div className="erp-metrics"><div><Package size={19}/><span>IL-7 장부 재고<strong>{analysis.need.ledger}<small>바이알</small></strong></span><Tag>모든 Lot 포함</Tag></div><div><ShieldCheck size={19}/><span>생산 가용재고<strong>{analysis.need.stock}<small>바이알</small></strong></span><Tag tone="green">품질·유효일 검증</Tag></div><div><ShoppingCart size={19}/><span>신규 필요 발주<strong>{analysis.need.required}<small>바이알</small></strong></span><Tag tone="blue">수요 + 안전 − 가용</Tag></div><div><Wallet size={19}/><span>잔여 구매예산<strong>{fmt(data.config.budget/10000)}<small>만원</small></strong></span><button onClick={()=>beginEdit('config',{id:'CONFIG'})} aria-label="예산·비용 설정 편집"><Pencil size={13}/></button></div></div>;
 const network=<div className="department-network"><div className="department-network-heading"><div><h2>부서별 판단 4개 → Admin 최종 조정</h2><p>각 부서가 유리하다고 판단한 안과, 그 안의 불리한 조건을 함께 확인합니다.</p></div><Tag tone={done?'green':running?'blue':'neutral'}>{done?'최종 검토 완료':running?'협의 진행 중':'분석 시작 대기'}</Tag></div><div className="department-verdicts">{verdicts.map(v=>{const a=agents[v.agent],ready=events.length>=v.readyAfter,active=inProgress?.agent===v.agent;return <article className={'department-verdict '+(ready?'ready':'pending')+(active?' judging':'')} key={v.department}><div className="verdict-heading"><a.icon size={23}/><h3>{v.department} AI</h3><span>{ready?'판단 제출':active?'판단 중':'대기'}</span></div><div className="verdict-priority">{v.priority}</div><h2>{ready?v.headline:active?'대안을 검토하고 있습니다':'데이터 검토 후 판단합니다'}</h2>{ready?<><p>{v.reason}</p><div className="verdict-tradeoff"><b>조정할 조건</b><p>{v.tradeoff}</p></div><button onClick={()=>{const ev=[...events].reverse().find(e=>e.agent===v.agent);if(ev)inspect(ev)}}>판단 근거 보기<ArrowRight size={16}/></button></>:<p className="verdict-wait">{active?'관련 ERP 데이터와 다른 부서의 근거를 대조하고 있습니다.':'담당 검토 단계가 실행되면 판단 결과가 표시됩니다.'}</p>}</article>})}</div><div className={'quality-gate '+(events.length>=10?'checked':'')}><ShieldCheck size={25}/><div><h3>QC/QA AI · 필수조건 검증</h3><p>{events.length>=10?`업체·제품 승인, Lot 유효일, 온도 기록과 QC ${data.config.qcDays}일·QA ${data.config.qaDays}일을 검증했습니다. ${analysis.options.filter(o=>o.deliveries.some(s=>s.qaHold)).length?'QA 보류 납품은 가용량에서 제외했습니다.':'예상 완료일과 실제 사용 승인은 구분합니다.'}`:'부서 제안과 별개로 품질·Lot·사용 가능일을 검증합니다. 품질 보류는 AI가 해제하지 않습니다.'}</p></div><Tag tone={events.length>=10?'green':'neutral'}>{events.length>=10?'검증 결과 반영':'검증 대기'}</Tag></div><div className={'admin-resolution '+(done?'resolved':'')}><div className="admin-heading"><BrainCircuit size={28}/><h3>Admin AI · 최종 조정</h3><span>{done?'최종 판단':'부서 의견 취합 중'}</span></div><h2>{done?analysis.need.required===0?'신규 발주 불필요':analysis.selected?`${analysis.selected}업체 ${analysis.recommendation!.quantity}바이알 · ${analysis.recommendation!.deliveries.length}회 입고`:'현재 조건에서는 발주 보류':'4개 부서의 결과를 확인한 뒤 하나의 안을 결정합니다'}</h2><p>{done?analysis.recommendation?`부서별 선호를 단순 투표하지 않습니다. 품질·확약·생산·예산·현금 조건을 모두 통과한 안 중 총비용 ${won(analysis.recommendation.total)}의 ${analysis.selected}안을 선택합니다. 구매·운송 소계는 ${won(analysis.recommendation.subtotal)}입니다.`:analysis.actions.join(' '):'단가, 폐기, 생산 여유, 총비용의 차이를 조정하고 필수조건을 충족하는 안만 최종 추천합니다.'}</p>{done&&<Button onClick={()=>go('recommendation')}><ClipboardCheck size={18}/>최종 추천서 · 담당자 승인<ArrowRight size={17}/></Button>}</div></div>;
 return <div className="app-shell erp-shell"><aside className="sidebar"><a className="brand" href="#" onClick={e=>{e.preventDefault();go('dashboard')}}><div className="brand-mark"><Blocks size={24}/></div><span>Bio<span className="brand-light">Flow</span><small>INTELLIGENT ERP</small></span></a><button className="workspace-switch" onClick={()=>setModal('source')}><div className="workspace-avatar">B</div><span><strong>바이오 제조 워크스페이스</strong><small>Pilot procurement · R{data.revision}</small></span><ChevronsUpDown size={12}/></button><div className="nav-label">WORKSPACE</div><nav>{nav.map((n,i)=><div key={n.id}>{i===3&&<div className="nav-divider"/>}<button className={'nav-item '+(page===n.id?'selected':'')} onClick={()=>go(n.id)}><n.icon size={18}/><span>{n.label}</span>{n.id==='workspace'&&<b className="nav-ai">AI</b>}</button></div>)}</nav><div className="sidebar-bottom"><div className="demo-card"><div><span className="green-dot"/><strong>Data-driven Demo</strong></div><p>실제 데이터 계산 · 규칙 기반 해석<br/>외부 LLM 호출 없음</p><button onClick={()=>setModal('source')}>scenario_1.pdf 근거<ArrowUpRight size={12}/></button></div><button className={'nav-item '+(page==='settings'?'selected':'')} onClick={()=>go('settings')}><Settings2 size={18}/><span>데이터 · 시연 설정</span></button><div className="user-profile"><div className="avatar">김</div><span><strong>김민서</strong><small>구매팀 · 가상 담당자</small></span></div></div></aside>
 <div className="main-shell"><header className="topbar"><div className="breadcrumb">워크스페이스<ChevronRight size={13}/><strong>{nav.find(n=>n.id===page)?.label||'데이터 · 시연 설정'}</strong></div><div className="top-actions"><span className="erp-mode"><span className="green-dot"/>ERP 계산 실행 · LLM 미연결</span><button className="revision-button" onClick={()=>setModal('history')}><History size={13}/>R{data.revision}</button><button className="icon-button" aria-label="업무 알림" onClick={()=>{go('production');setToast(`현재 B안 생산 부족 ${analysis.options[1].shortage}개 · QA 보류/예측 상태를 확인하세요.`)}}><Bell size={18}/></button><button className="icon-button" aria-label="업무형 데모 안내" onClick={()=>setModal('help')}><CircleHelp size={18}/></button><div className="mini-avatar">김</div></div></header>
 <main>
 {page==='dashboard'&&<>
 {heading('PROCUREMENT CONTROL CENTER','원료 발주 업무 현황','재고의 숫자부터 생산 투입 조건까지, 같은 데이터로 연결합니다.',<><span className="erp-date"><CalendarDays size={14}/>2026.10.24 기준</span><Button onClick={start}><Network size={15}/>IL-7 발주 분석</Button></>)}
 <div className="erp-work-alert"><div className="erp-alert-symbol"><FlaskConical size={23}/></div><div><b>MAT-IL7 · 장부 재고와 생산 가용재고가 다릅니다.</b><p>장부 {analysis.need.ledger}개 → 품질·유효일 검증 후 {analysis.need.stock}개. 신규 발주 {analysis.need.required}개를 투입 일정에 맞춰 확보하세요.</p></div><button onClick={()=>{go('inventory');setSelectedRow(null)}}>Lot 검토<ArrowRight size={14}/></button><Tag tone="blue">{scenarios.find(s=>s.id===data.config.scenario)?.name}</Tag></div>
 {metrics}
 <div className="erp-section-heading"><div><h3>생산 조달 워크리스트</h3><p>원료 투입일을 마감으로 판정 · 고객 납품 일정은 별도 검증 필요</p></div><div className="candidate-picker"><span>검토 공급안</span><select aria-label="워크리스트 공급안" value={candidate} onChange={e=>setCandidate(e.target.value)}>{data.vendors.map(v=><option key={v.id} value={v.id}>{v.name}</option>)}</select></div></div>
 <Panel>{grid('production')}</Panel><div className="erp-dashboard-lower"><Panel><div className="panel-title"><div><h3>원료 Lot별 가용성 검토</h3><p>셀 선택 시 참조 문서와 제외 사유를 확인할 수 있습니다.</p></div><button className="text-button" onClick={()=>go('inventory')}>원료·Lot 관리<ArrowRight size={13}/></button></div>{grid('lots')}</Panel><Panel className="erp-dashboard-chart"><div className="panel-title"><div><h3>{candidate}안 · 생산 가용재고 예측</h3><p>입고 시점이 아닌 QC/QA 예상 완료일 기준</p></div><Tag tone="blue">바이알</Tag></div>{chart()}<div className="erp-chart-foot"><span className="green-dot"/>현재 승인 재고 {analysis.need.stock} · 미래 입고분은 예측</div><div className="erp-dashboard-facts"><div><span>IL-15 동반 원료</span><b>{analysis.il15.available}개 승인 / 수요 {analysis.il15.need}개</b><Tag tone={analysis.il15.ok?'green':'red'}>{analysis.il15.ok?'충분':'부족'}</Tag></div><div><span>A/B 구매·운송 소계 차이</span><b>{won(analysis.options[0].subtotal-analysis.options[1].subtotal)}</b></div><div><span>원본 데이터</span><button onClick={()=>setModal('source')}>PDF와 합성 확장 구분<ArrowUpRight size={12}/></button></div></div></Panel></div>
 </>}
 {page==='workspace'&&<>
 {heading('MULTI-AGENT ANALYSIS WORKSPACE','IL-7 발주 검토 회의','구매 · 재고 · 생산 · 재무 판단을 비교하고 품질 검증 후 최종안을 결정합니다.',<><Button variant="outline" onClick={()=>setModal('scenario')}><Zap size={14}/>변형 시나리오</Button><Button onClick={start}><RefreshCw size={14}/>{started?'새 데이터로 재분석':'분석 시작'}</Button></>)}
 <div className="erp-workspace-context"><Tag tone="blue">MAT-IL7</Tag><b>{scenarios.find(s=>s.id===data.config.scenario)?.name}</b><span>생산 {analysis.need.total} + 안전 {analysis.need.safety} − 가용 {analysis.need.stock} = <strong>신규 {analysis.need.required}바이알</strong></span>{data.changes[0]&&data.changes[0].entity!=='SCENARIO'&&<Tag tone="amber">사용자 편집 반영</Tag>}<span className="context-revision">ERP 데이터 R{data.revision}</span></div>
 {stale&&<div className="erp-stale"><AlertTriangle size={17}/><div><b>이전 추천 R{report?.revision}은 유효하지 않습니다.</b><span>현재 데이터 R{data.revision}로 다시 검증해야 합니다. 옛 추천의 PO 생성을 차단했습니다.</span></div><button onClick={start}>재분석<ArrowRight size={13}/></button></div>}
 <Panel className="department-deliberation">{network}</Panel><div className="erp-workspace-grid"><div className="erp-workspace-data"><Panel><div className="panel-title"><div><h3><Database size={16}/>ERP 데이터 · 실행 중인 참조</h3><p>{running?phase.label:'탭과 셀을 선택해 원본 데이터를 확인하세요.'}</p></div><Tag>R{data.revision}</Tag></div>{tableTabs}{grid(table,true)}<div className="erp-cell-hint"><Pencil size={12}/>편집 후 연결 화면·계산은 즉시 갱신됩니다. 추천은 재분석 후 유효해집니다.</div>{selectedRow&&selectedRow.table===table&&<div className="workspace-cell-detail"><DetailBody row={selectedRow.row} kind={table} data={data}/></div>}</Panel>
 <Panel className="erp-formula-panel"><div className="panel-title"><h3><BarChartIcon/>계산식과 데이터 흐름</h3><Tag tone="blue">결정론적 계산</Tag></div>{latest?<div className="active-calculation"><div><span>{latest.id}</span><b>{latest.title}</b></div><code>{latest.formula}</code><p>{latest.result}</p><button className="text-button" onClick={()=>inspect(latest)}>실행 시점 스냅샷 확인<ArrowRight size={13}/></button></div>:<div className="erp-formula-empty"><Database size={24}/><strong>분석을 시작하면 실제 조회·계산 근거가 표시됩니다.</strong><p>행 강조는 실행된 이벤트의 참조 ID와 연결됩니다.</p></div>}</Panel>
 <Panel className="erp-schedule-chart"><div className="panel-title"><h3>{candidate}안 · 분할 입고와 재고</h3><select aria-label="분석 차트 공급안" value={candidate} onChange={e=>setCandidate(e.target.value)}>{data.vendors.map(v=><option key={v.id} value={v.id}>{v.id}안</option>)}</select></div>{chart()}</Panel></div>
 <div className="erp-workspace-center"><Panel><div className="panel-title"><h3>분석 작업 실행</h3><Tag>작업별 가변 속도</Tag></div><div className="erp-playback"><div className="erp-run-progress" role="progressbar" aria-label="실제 분석 작업 진행률" aria-valuenow={events.length} aria-valuemin={0} aria-valuemax={stages.length}><i style={{width:events.length/stages.length*100+'%'}}/></div><div className="erp-playback-info"><b>{events.length} / {stages.length} 작업 실행</b><span>{running?`${phase.label} · ${stagePlaybackMs(data,events.length,intervalMs)/1000}초 재생`:done?'분석 완료':started?'일시정지':'시작 대기'}</span></div><div className="erp-play-buttons"><Button onClick={()=>{if(!started||done)start();else setRunning(!running)}}>{running?<Pause size={14}/>:<Play size={14}/>} {running?'일시정지':done?'다시 실행':started?'계속 실행':'분석 시작'}</Button><Button variant="outline" aria-label="남은 계산 모두 실행" disabled={done} onClick={skip}><SkipForward size={15}/></Button><select aria-label="분석 재생 간격" value={intervalMs} onChange={e=>setIntervalMs(Number(e.target.value))}><option value={900}>빠르게</option><option value={1800}>기본</option><option value={4000}>발표용</option></select></div></div></Panel>
 <Panel className="erp-log-panel"><div className="panel-title"><h3><History size={15}/>분석 작업 로그</h3><Tag>{events.length} events</Tag></div><div className="erp-log-list" ref={logRef}>{events.length?events.map(ev=><button className={'erp-log-item '+ev.tone+(selectedEvent?.id===ev.id?' selected':'')} key={ev.id} onClick={()=>inspect(ev)}><span className="log-agent-dot" style={{background:agents[ev.agent].color}}/><div><small>{agents[ev.agent].name}<i>{ev.id}</i></small><strong>{ev.title}</strong><p>{ev.result}</p></div><ChevronRight size={12}/></button>):<div className="erp-log-empty"><History size={24}/><p>실제로 실행된 조회·계산만<br/>작업 로그에 기록됩니다.</p></div>}</div></Panel></div>
 <div className="erp-workspace-results"><Panel className="erp-live-result"><div className="panel-title"><h3><BrainCircuit size={17}/>의사결정 보드</h3><Tag tone={analysis.selected?'green':'amber'}>{analysis.need.required===0?'발주 불필요':analysis.selected?'적격 후보 있음':'조치 필요'}</Tag></div><div className="decision-stage"><small>{events.length<5?'01 · ERP 가용량 검토':events.length<8?'02 · 최초 제안의 재검증':events.length<11?'03 · 일정·품질 검증':'04 · 최종 전략 도출'}</small><h2>{events.length<5?'재고를 먼저 검증합니다':events.length<8?`${firstPriceVendor?.id||'—'}안 · 조건 검토`:analysis.selected?`${analysis.selected}안 · 조건 검증`:'추천 보류 · 제약 발생'}</h2><p>{events.length<5?`장부 ${analysis.need.ledger}개와 가용 ${analysis.need.stock}개를 구분합니다.`:events.length<8?`${firstPriceVendor?.id||'—'} MOQ 반영 ${initialOption?.quantity||0}개, 예상 폐기 ${initialOption?.waste||0}개. 단가와 총 지출을 함께 검증합니다.`:analysis.recommendation?`${analysis.recommendation.quantity}개 · ${analysis.recommendation.deliveries.length}회 입고 · 최종 총비용 ${won(analysis.recommendation.total)}`:analysis.actions[0]}</p></div><div className="strategy-change"><div><span>최초 검토</span><b>{firstPriceVendor?.id||'없음'} · 단가 {firstPriceVendor?won(firstPriceVendor.unitPrice):'—'}</b></div><ArrowRight size={16}/><div><span>재계산 후</span><b>{done&&report&&!stale?report.analysis.selected?`${report.analysis.selected}안 추천`:'발주 보류':'검토 진행 / 미확정'}</b></div></div><div className="erp-constraint-list">{analysis.options.map(o=><div key={o.id}><span className="supplier-letter">{o.id}</span><div><b>{won(o.subtotal)}</b><small>{o.eligible?'필수조건 충족':o.constraints[0]}</small></div>{o.eligible?<CheckCircle2 size={15}/>:<AlertTriangle size={15}/>}</div>)}</div><Button className="full-width" onClick={()=>go('recommendation')} disabled={!report||stale||running}><ClipboardCheck size={15}/>최종 추천서 확인</Button></Panel>
 <Panel className="erp-proof-card"><div className="panel-title"><h3>판정 기준</h3></div><p><Check size={13}/>동일 제품 · 공급 확약</p><p><Check size={13}/>생산 투입일 · QC/QA</p><p><Check size={13}/>예산과 지급일 현금 별도</p><p><Check size={13}/>현재 재고와 미래 예측 분리</p><small>규칙 기반 해석 · 외부 AI 호출 없음<br/>AI는 품질 보류를 승인하지 않습니다.</small></Panel></div></div>
 </>}
 {page==='recommendation'&&<>
 {heading('PURCHASE REVIEW & APPROVAL','발주 검토 · 최종 추천서','원본 revision, 필수조건 검증, 근거를 확인한 뒤 내부 가상 PO를 등록합니다.',<><Button variant="outline" onClick={revisionVariant}><Pencil size={14}/>승인 직전 수요 변경</Button><Button onClick={start}><RefreshCw size={14}/>데이터 재분석</Button></>)}
 {!report?<Panel><div className="erp-empty"><BrainCircuit size={35}/><h2>검증된 분석 결과가 아직 없습니다.</h2><p>AI Workspace에서 실제 ERP 데이터를 조회하고 계산해 추천서를 생성하세요.</p><Button onClick={start}><Play size={15}/>분석 시작</Button></div></Panel>:<>
 {stale&&<div className="erp-stale"><AlertTriangle size={20}/><div><b>추천 만료 · R{report.revision} → R{data.revision}</b><span>아래는 당시 스냅샷입니다. 원본 데이터가 변경되어 이 추천으로는 PO를 생성할 수 없습니다.</span></div><button onClick={start}>현재 데이터로 재검증<ArrowRight size={14}/></button></div>}
 <div className={'erp-final-summary '+(!report.analysis.recommendation?'blocked':'')}><div className="summary-emblem">{report.analysis.recommendation?<CheckCheck size={28}/>:<AlertTriangle size={28}/>}</div><div><div className="eyebrow">ADMIN AI · VERIFIED ERP CALCULATION · R{report.revision}</div><h2>{report.analysis.recommendation?`${report.analysis.recommendation.name} · IL-7 ${report.analysis.recommendation.quantity}바이알 추천`:report.analysis.need.required===0?'기존 승인 재고로 충족되어 신규 발주가 필요하지 않습니다.':'현재 조건을 충족하는 공급안이 없습니다. 발주를 보류합니다.'}</h2><p>{report.analysis.recommendation?`구매·운송 ${won(report.analysis.recommendation.subtotal)} · 최종 총비용 ${won(report.analysis.recommendation.total)} · 예상 폐기 ${report.analysis.recommendation.waste}개`:'확약되지 않은 공급량이나 품질 보류 Lot를 가용 재고로 계산하지 않았습니다.'}</p></div><button className="text-button" onClick={()=>setModal('history')}>분석 스냅샷<History size={14}/></button></div>
 <div className="erp-report-meta"><span>분석번호 <b>{report.id}</b></span><span>계산 기준일 <b>{BASE}</b></span><span>판정 마감 <b>생산별 원료 투입일</b></span><Tag tone={stale?'red':'green'}>{stale?'STALE':'원본 일치'}</Tag></div>
 <div className="erp-recommendation-layout"><div><Panel><div className="panel-title"><div><h3>변경 전·후 발주 전략 비교</h3><p>단가 우선 제안 → 총비용·공급·생산 제약 재검토 · 당시 R{report.revision}</p></div><Tag tone="blue">계산 스냅샷</Tag></div><DataGrid title="추천 비용 스냅샷" rows={getRows(report.data,report.analysis,'costs')} columns={columns.costs} revision={report.revision} onSelect={(row,column)=>setSelectedRow({row,column,table:'costs'})} onExport={setToast}/><div className="erp-subtotal-note"><Wallet size={15}/><span>구매·운송 소계 차이 <b>{won(report.analysis.options[0].subtotal-report.analysis.options[1].subtotal)}</b> · 최종 총비용 차이 <b>{won(report.analysis.options[0].total-report.analysis.options[1].total)}</b></span></div></Panel>
 <Panel className="erp-cost-chart-panel"><div className="panel-title"><div><h3>비용 구성 비교</h3><p>구매·운송 소계 + 시험 + 보관 + 폐기처리 · 구매원가에 포함된 폐기 장부가액은 중복 가산하지 않습니다.</p></div></div><div className="erp-cost-chart"><ResponsiveContainer width="100%" height="100%"><BarChart data={report.analysis.options} margin={{top:5,left:20,right:20,bottom:0}}><CartesianGrid vertical={false} strokeDasharray="3 5" stroke="#e9edf5"/><XAxis dataKey="id" tickFormatter={v=>v+'안'} tick={{fontSize:14,fill:'#8598b4'}} axisLine={false} tickLine={false}/><YAxis tickFormatter={v=>Math.round(v/10000)+'만'} tick={{fontSize:13,fill:'#8598b4'}} axisLine={false} tickLine={false}/><Tooltip formatter={(v)=>won(Number(v))} contentStyle={{fontSize:14,borderRadius:8}}/><Legend wrapperStyle={{fontSize:13}}/><ReferenceLine y={report.data.config.budget} stroke="#c89f62" strokeDasharray="4 4"/><Bar dataKey="subtotal" name="구매·운송" stackId="cost" fill="#6f91d0" maxBarSize={58}/><Bar dataKey="testing" name="시험비" stackId="cost" fill="#91b8af"/><Bar dataKey="storage" name="보관비" stackId="cost" fill="#b0a3d0"/><Bar dataKey="disposal" name="폐기처리" stackId="cost" fill="#dab490" radius={[4,4,0,0]}/></BarChart></ResponsiveContainer></div></Panel>
 <Panel className="erp-report-timing"><div className="panel-title"><div><h3>지급일별 현금 한도 검증</h3><p>구매·운송·시험비 회차별 지급 + 계획 종료일 보관·폐기처리비 · 동일 지급일은 합산</p></div><Tag>예산과 별도</Tag></div><DataGrid title="지급일 현금 검증" rows={report.analysis.options[1].cash.map(c=>({...c,status:c.ok?'현금 한도 내':'현금 한도 부족',tone:c.ok?'':'danger'}))} columns={[{key:'id',label:'지급 근거'},{key:'date',label:'지급일',kind:'date'},{key:'amount',label:'예상 지급액',kind:'number',format:v=>won(Number(v))},{key:'limit',label:'해당일 한도',kind:'number',format:v=>won(Number(v))},{key:'status',label:'현금 검증'}]} revision={report.revision} onExport={setToast}/></Panel>
 <Panel className="erp-report-timing"><div className="panel-title"><div><h3>B 분할안 · 회차별 가용일과 생산 투입</h3><p>기준 스냅샷의 QC/QA 예상 완료일 · 실제 승인 별도</p></div><Tag>입고 3회</Tag></div><ScheduleTable option={report.analysis.options[1]} data={report.data}/></Panel>
 {report.analysis.actions.length>0&&<Panel className="erp-required-actions"><div className="panel-title"><h3><AlertTriangle size={16}/>수정 전략 · 담당자 조치 필요</h3></div>{report.analysis.actions.map((action,i)=><div key={action}><span>{String(i+1).padStart(2,'0')}</span><p>{action}</p></div>)}<div className="erp-action-foot">대안은 제안입니다. 공급업체 확약·일정 변경·QC 슬롯 조정이 승인되기 전에는 확정 공급으로 계산하지 않습니다.</div></Panel>}
 </div><div className="erp-approval-sidebar"><Panel className="erp-approval-card"><div className="panel-title"><h3>담당자 발주 검토</h3><ClipboardCheck size={19}/></div><dl><div><dt>추천 공급안</dt><dd>{report.analysis.selected?`${report.analysis.selected} 공급업체`:'해당 없음'}</dd></div><div><dt>발주 수량</dt><dd>{report.analysis.recommendation?.quantity??'—'} 바이알</dd></div><div><dt>구매·운송 소계</dt><dd>{report.analysis.recommendation?won(report.analysis.recommendation.subtotal):'—'}</dd></div><div><dt>추가 비용 포함</dt><dd>{report.analysis.recommendation?won(report.analysis.recommendation.total):'—'}</dd></div><div><dt>단일 합산 예산</dt><dd>{won(report.data.config.budget)}</dd></div></dl><div className="erp-approval-checks"><p><ShieldCheck size={15}/>제품·업체 승인과 회차별 확약</p><p><CalendarDays size={15}/>QC/QA 이후 생산 투입 충족</p><p><Wallet size={15}/>총비용·현금 한도·보관 용량</p></div><Button className="full-width" disabled={approvalProblems.length>0} onClick={()=>setModal('approve')}><Check size={15}/>가상 발주 승인</Button>{approvalProblems.length>0&&<div className="erp-approval-errors">{approvalProblems.map(s=><p key={s}>{s}</p>)}</div>}<p className="erp-approval-notice">발주 승인은 품질 사용 승인이 아닙니다.<br/>현재 가용재고와 Lot QC/QA는 바뀌지 않습니다.</p></Panel>
 <Panel className="erp-residual-panel"><div className="panel-title"><h3>잔여 위험 · 추가 확인</h3></div>{report.analysis.warnings.map(w=><p key={w}><AlertTriangle size={12}/>{w}</p>)}<p><FileText size={12}/>고객 납품 일정은 합성 관리값으로, 원료 투입 충족만으로 고객 납기 준수를 확정하지 않습니다.</p><p><Package size={12}/>보류·만료 Lot도 실제 반출 전까지 보관 공간을 점유합니다.</p></Panel></div></div>
 <Panel className="erp-qa"><div className="panel-title"><div><h3><MessageSquare size={16}/>데이터에 질문하기</h3><p>현재 R{data.revision} 계산값을 해석하는 규칙 기반 응답 · 외부 LLM 호출 없음</p></div><Tag tone="blue">데이터 연결 해설</Tag></div><div className="erp-question-chips">{['단가가 싼 A보다 B의 비용이 낮은 이유는?','QC 지연은 어떤 생산에 영향을 줘?','C 업체를 선택할 수 없는 이유는?','재고 6개를 모두 쓸 수 없어?'].map(q=><button key={q} onClick={()=>ask(q)}>{q}<ArrowUpRight size={12}/></button>)}</div><form className="erp-question-input" onSubmit={e=>{e.preventDefault();if(question.trim())ask(question)}}><input aria-label="ERP 데이터 질문" value={question} onChange={e=>setQuestion(e.target.value)} placeholder="재고, 비용, C 공급업체, QC 지연에 대해 질문하세요"/><Button type="submit" disabled={!question.trim()}><ArrowRight size={15}/>질문</Button></form>{answer&&<div className="erp-answer" aria-live="polite"><BrainCircuit size={19}/><p>{answer}</p></div>}</Panel>
 </>}
 </>}
 {(page==='inventory'||page==='suppliers'||page==='production')&&<>
 {heading(page==='inventory'?'MATERIAL & LOT CONTROL':page==='suppliers'?'SOURCING & COMMITMENTS':'PRODUCTION & RECEIPT PLANNING',page==='inventory'?'원료 · Lot 재고':page==='suppliers'?'견적 · 공급 확약':'생산 · 입고 계획',page==='inventory'?'가용재고는 품질 상태와 최초 투입일의 유효성으로 판정합니다.':page==='suppliers'?'단가·MOQ·확약·승인 조건을 구분하고, 회차별 공급 근거를 확인하세요.':'원료 최초 투입일과 QC/QA 예상 완료일을 연결해 부족을 확인합니다.',<><Button variant="outline" onClick={()=>setModal('scenario')}><Zap size={14}/>변형 시나리오</Button><Button onClick={start}><Network size={14}/>변경 데이터 분석</Button></>)}
 {page==='inventory'&&metrics}
 <Panel><div className="panel-title"><div><h3>{tableLabels[table]}</h3><p>행의 셀을 선택해 상세 확인 · 편집 저장 시 관련 화면 자동 갱신</p></div><div className="candidate-picker"><span>생산 판정 공급안</span><select aria-label="생산 판정 공급안" value={candidate} onChange={e=>setCandidate(e.target.value)}>{data.vendors.map(v=><option key={v.id} value={v.id}>{v.id}안</option>)}</select></div></div>{tableTabs}{grid(table)}</Panel>
 {selectedRow&&<Panel className="erp-inline-detail"><div className="panel-title"><div><h3><Search size={15}/>선택 셀 · {selectedRow.row.id} / {columns[selectedRow.table].find(c=>c.key===selectedRow.column)?.label}</h3><p>원본 데이터와 문서 참조를 함께 확인하세요.</p></div><button className="icon-button" aria-label="선택 상세 닫기" onClick={()=>setSelectedRow(null)}><X size={16}/></button></div><DetailBody row={selectedRow.row} kind={selectedRow.table} data={data}/></Panel>}
 <div className="erp-management-bottom"><Panel><div className="panel-title"><h3>{candidate}안 · 재고와 생산 투입 예측</h3><Tag>바이알</Tag></div>{chart()}<div className="erp-chart-foot">공급 미확약·QA 보류 납품분은 예측 가용량에서도 제외합니다.</div></Panel><Panel><div className="panel-title"><h3>품질 · 공급 관리 원칙</h3></div><div className="erp-policy-notes"><p><ShieldCheck size={17}/>품질 보류 해제에는 QC 근거와 QA 담당자 서명이 필요합니다. 수량·일정을 편집해도 품질 상태는 변경되지 않습니다.</p><p><Package size={17}/>IL-7과 IL-15는 독립된 승인 제품이며 동일 함량의 바이알 단위만 사용합니다. 재구성 잔량의 재사용은 지원하지 않습니다.</p><p><FileText size={17}/>B 분할 계약 CTR-B-01: 미출하 회차 변경·취소는 공급업체의 서면 동의가 필요합니다.</p><p><Database size={17}/>제품·Lot·CoA·확약 ID는 합성 ERP 근거입니다. 실제 제품의 공식 규격 등록이 필요합니다.</p></div></Panel></div>
 </>}
 {page==='orders'&&<>
 {heading('PURCHASE ORDERS & AUDIT TRAIL','발주 · 변경 이력','발주 당시 스냅샷을 보존하고, 변경된 원본과의 일치 여부를 다시 확인합니다.',<Button variant="outline" onClick={()=>setModal('history')}><History size={14}/>분석 버전 이력</Button>)}
 <div className="erp-order-stats"><Panel><FileText size={20}/><span>등록된 PO<b>{orders.length}건</b></span></Panel><Panel><CheckCircle2 size={20}/><span>원본 일치<b>{currentOrders.filter(o=>o.status==='가상 발주 승인').length}건</b></span></Panel><Panel><AlertTriangle size={20}/><span>데이터 변경 · 재검토<b>{currentOrders.filter(o=>o.status==='재검토 필요').length}건</b></span></Panel></div>
 <Panel><div className="panel-title"><h3>가상 발주 내역</h3><Tag>실제 주문 없음</Tag></div><DataGrid title="가상 발주 내역" rows={currentOrders.map(o=>({...o,id:o.id,status:o.status,tone:o.status==='재검토 필요'?'warning':'',created:o.createdAt.slice(0,10),material:'MAT-IL7',quality:'미입고 · 사용 미승인',report:o.report}))} columns={orderColumns} revision={data.revision} onSelect={(row)=>{const o=orders.find(o=>o.id===row.id)!;setToast(`${o.id} · ${o.shipments.length}회차 납품 예정 · 발주 당시 R${o.revision} 스냅샷 보존`);setSelectedRow({row:{...row,shipments:o.shipments},column:'id',table:'shipments'})}} onExport={setToast}/></Panel>
 {selectedRow?.row.id.startsWith('PO-')&&<Panel className="erp-order-detail"><div className="panel-title"><h3>{selectedRow.row.id} · 발주 당시 납품 회차</h3><Tag>스냅샷</Tag></div><DataGrid title="PO 입고 회차" rows={(selectedRow.row.shipments as Option['deliveries']).map(s=>({...s,status:'계획 입고 · 실제 사용 미승인'}))} columns={columns.shipments.filter(c=>c.key!=='vendor')} revision={Number(selectedRow.row.revision)} onExport={setToast}/></Panel>}
 <Panel className="erp-change-log"><div className="panel-title"><h3>ERP 데이터 변경 추적</h3><Tag>{data.changes.length} changes</Tag></div><DataGrid title="데이터 변경 이력" rows={data.changes.map(c=>({...c,status:'R'+c.id.replace('CHG-',''),time:new Date(c.at).toLocaleTimeString('ko-KR')}))} columns={[{key:'id',label:'변경 ID'},{key:'entity',label:'대상 ID'},{key:'field',label:'변경 필드'},{key:'before',label:'변경 전'},{key:'after',label:'변경 후'},{key:'time',label:'기록 시각'}]} revision={data.revision} onExport={setToast}/></Panel><div className="notice"><ShieldCheck size={16}/>데이터 변경은 기존 주문을 자동 취소하지 않습니다. 재검토 필요로 표시하고 당시 승인 스냅샷을 유지합니다.</div>
 </>}
 {page==='settings'&&<>
 {heading('WORKSPACE SETTINGS','데이터 · 시연 설정','원본 PDF의 기준과 추가 합성 설정을 구분하고, 필요한 업무 변형을 검증합니다.')}
 <div className="erp-settings-layout"><Panel><div className="panel-title"><h3>계산 엔진 설정</h3><Button variant="outline" onClick={()=>beginEdit('config',{id:'CONFIG'})}><Pencil size={13}/>편집</Button></div><dl className="erp-config-dl">{(['budget','qcDays','qaDays','testingPerLot','storagePerVialDay','disposalPerVial'] as const).map(k=><div key={k}><dt>{editLabels[k]}</dt><dd>{fmt(data.config[k])}</dd></div>)}</dl><div className="erp-budget-allocation"><b>단일 예산의 귀속 · 중복 합산 없음</b>{data.productions.map(p=><p key={p.id}><span>{p.id}</span><strong>{won(p.budget)}</strong></p>)}<p><span>안전재고 공통원가 귀속</span><strong>{won(data.config.safetyBudget)}</strong></p><p><span>배분 합계</span><strong>{won(data.productions.reduce((n,p)=>n+p.budget,0)+data.config.safetyBudget)}</strong></p>{data.productions.reduce((n,p)=>n+p.budget,0)+data.config.safetyBudget!==data.config.budget&&<small>편집한 잔여 예산과 합성 배분이 다릅니다. 재무 담당자의 재배분 확인이 필요합니다.</small>}</div><div className="erp-config-note">추가 비용 단가는 PDF에 없는 합성 가정입니다. 설정값은 비용 비교·예산 적격성에 실제 반영됩니다.</div><div className="erp-setting-row"><span>분석 재생 속도 · 작업별 소요 차등</span><select aria-label="설정 분석 재생 간격" value={intervalMs} onChange={e=>setIntervalMs(Number(e.target.value))}><option value={900}>빠르게 · 작업별 가변</option><option value={1800}>기본 · 작업별 가변</option><option value={4000}>발표용 · 작업별 가변</option></select></div><div className="erp-setting-row"><span>기존 FGF-2 발표 데모<small>이전 UI와 주요 기능을 별도 유지</small></span><Button variant="outline" onClick={onLegacy}>기존 데모 열기<ArrowUpRight size={13}/></Button></div><div className="erp-setting-row"><span>전체 업무 데이터 초기화<small>편집·가상 PO·분석 이력 삭제</small></span><Button variant="danger" onClick={()=>setModal('reset')}><RotateCcw size={13}/>초기화</Button></div></Panel>
 <Panel><div className="panel-title"><h3>실행 모드와 근거</h3><Tag tone="green">ERP 계산 실행</Tag></div><div className="erp-mode-description"><Database size={25}/><h3>실제 데이터 조회·계산 + 규칙 기반 해석</h3><p>작업 로그는 실행된 조회·검증 함수의 결과로 생성됩니다. 해설 문장은 현재 계산값에서 구성하며 외부 LLM은 호출하지 않습니다.</p><h4>Tool Calling · Structured Output 확장</h4><p>읽기 전용 ERP 도구의 JSON 스키마와 구조화 검증 경계를 제공합니다. 실제 API 서버는 미연결이며, 모델 설명으로 품질 상태나 PO를 자동 변경하지 않습니다.</p><button className="text-button" onClick={()=>setModal('source')}>PDF와 추가 합성 데이터 대조<ArrowRight size={14}/></button></div></Panel></div>
 <Panel className="erp-scenario-settings"><div className="panel-title"><h3>독립 변형 시나리오</h3><p>매번 기준 데이터에서 적용 · 이전 추천과 PO는 재검토 필요로 전환</p></div><div className="erp-scenario-grid">{scenarios.map(s=><button key={s.id} onClick={()=>changeScenario(s.id)} className={data.config.scenario===s.id?'active':''}><div><Zap size={16}/><b>{s.name}</b>{data.config.scenario===s.id&&<Check size={14}/>}</div><p>{s.description}</p><small>{s.source}</small></button>)}</div></Panel>
 </>}
 <div className="erp-page-footnote"><Database size={12}/><span>scenario_1.pdf 기반 합성 ERP · 동일 함량 바이알 단위 · 실제 AI 호출·구매·품질 승인 없음</span><button onClick={()=>setModal('source')}>데이터 출처 확인<ArrowUpRight size={11}/></button></div>
 </main><footer className="app-footer"><span className="footer-brand">BioFlow <span>Decisions with evidence.</span></span><span><span className="green-dot"/>DATA-DRIVEN DEMO<i/>R{data.revision} · 기준일 2026.10.24</span></footer></div>
 <Modal title="독립 변형 시나리오" open={modal==='scenario'} onClose={()=>setModal(null)} wide><div className="erp-modal-intro"><Zap size={23}/><div><h2>데이터를 바꾸면, 판단도 바뀝니다.</h2><p>각 변형은 기준 데이터에서 독립 실행합니다. 기존 추천과 승인 PO는 보존하되 재검토 상태가 됩니다.</p></div></div><div className="erp-scenario-grid">{scenarios.map(s=><button key={s.id} onClick={()=>changeScenario(s.id)} className={data.config.scenario===s.id?'active':''}><div><Zap size={15}/><b>{s.name}</b></div><p>{s.description}</p><small>{s.source}</small></button>)}</div></Modal>
 <Modal title="원본 데이터 · 추가 합성 설정" open={modal==='source'} onClose={()=>setModal(null)} wide><div className="erp-source-links"><Tag tone="blue">scenario_1.pdf · 2026.10.24 · 5 pages</Tag><a href="./references/scenario_1.pdf" target="_blank" rel="noreferrer">원문 PDF 열기 ↗</a><a href="./erp-seed.json" target="_blank" rel="noreferrer">기준 JSON ↗</a></div><h2 className="erp-modal-h2">원문 기준과 ERP 확장을 구분합니다.</h2><p>모든 가격·수요·승인 기록은 합성 데이터입니다. 임상·상업 제조 적합성이나 실제 공급 확약을 의미하지 않습니다.</p><div className="erp-source-list">{sourceNotes.map(n=><div key={n.field}><Tag tone={n.status==='원문 반영'?'green':'amber'}>{n.status}</Tag><strong>{n.field}</strong><p>{n.source}</p></div>)}</div><div className="notice"><ShieldCheck size={16}/>실제 제품의 함량과 공식 보관 온도를 이 문서만으로 확정하지 않았습니다. 합성 규격 U1/U2는 변환계수 1인 별도 제품 식별자이며 실제 함량으로 환산하지 않습니다.</div></Modal>
 <Modal title="실행 이벤트 · 계산 근거" open={!!inspectedEvent} onClose={()=>setInspectedEvent(null)} wide>{inspectedEvent&&<><div className="erp-evidence-heading"><Tag tone="blue">{inspectedEvent.id}</Tag><Tag>R{inspectedEvent.revision} · 실행 스냅샷</Tag><strong>{agents[inspectedEvent.agent].name}</strong></div><h2 className="erp-modal-h2">{inspectedEvent.title}</h2><code className="erp-evidence-formula">{inspectedEvent.formula}</code><p>{inspectedEvent.result}</p><div className="erp-evidence-grid"><DataGrid title="참조 스냅샷" rows={inspectedEvent.snapshot.map(r=>{const obj:Row={id:String(r.id)};for(const [k,v] of Object.entries(r))obj[k]=typeof v==='object'?JSON.stringify(v):v;return obj})} columns={[{key:'id',label:'참조 ID'},...columns[inspectedEvent.table].filter(c=>c.key!=='id'&&inspectedEvent.columns.includes(c.key))]} revision={inspectedEvent.revision} highlightRows={inspectedEvent.rows} highlightCols={inspectedEvent.columns} onExport={setToast}/></div><div className="erp-evidence-refs"><b>참조 행 ID</b><p>{inspectedEvent.rows.join(' · ')||'해당 없음'}</p><b>조회 결과 기록 시각</b><p>{new Date(inspectedEvent.at).toLocaleString('ko-KR')}</p></div><div className="notice">현재 ERP와 다를 수 있는 실행 당시 데이터입니다. 변경된 원본으로 승인하려면 재분석해야 합니다.</div></>}</Modal>
 <Modal title="ERP 데이터 편집" open={!!editing} onClose={()=>setEditing(null)} wide>{editing&&<form onSubmit={e=>{e.preventDefault();submitEdit()}}><div className="erp-edit-heading"><Tag tone="blue">{editing.id}</Tag><span>R{data.revision} → R{data.revision+1}</span></div><div className="erp-edit-fields">{Object.entries(editing.values).map(([key,value])=><label key={key}><span>{editLabels[key]||key}</span><input aria-label={editLabels[key]||key} type={dateFields.has(key)?'date':'number'} min="0" step={['unitPrice','shipping','budget','testingPerLot','storagePerVialDay','disposalPerVial','cashLimit'].includes(key)?'any':'1'} value={value} onChange={e=>setEditing({...editing,values:{...editing.values,[key]:e.target.value}})} required/></label>)}</div>{editing.type==='production'&&<div className="notice">투입일 변경 시 합성 후속 일정은 완료 +5일, 납품 +8일로 연결됩니다. 실제 고객 납기 준수는 별도로 확인해야 합니다.</div>}<div className="notice"><ShieldCheck size={15}/>품질 보류·QA 승인 상태는 여기서 편집하지 않습니다. 수량·일정 변경만으로 품질이 승인되거나 추가 공급이 확약되지 않습니다.</div>{editError&&<p role="alert" className="erp-form-error">{editError}</p>}<div className="modal-actions"><Button variant="outline" type="button" onClick={()=>setEditing(null)}>취소</Button><Button type="submit"><Check size={14}/>저장 · 연결 데이터 갱신</Button></div></form>}</Modal>
 <Modal title="담당자 가상 발주 승인" open={modal==='approve'} onClose={()=>setModal(null)}>{report?.analysis.recommendation&&<><div className="modal-illustration blue"><ClipboardCheck size={28}/></div><h2 className="erp-modal-h2">검증된 조건으로 내부 PO를 등록합니다.</h2><dl className="confirm-dl"><div><dt>공급업체</dt><dd>{report.analysis.recommendation.name}</dd></div><div><dt>원료 / 수량</dt><dd>MAT-IL7 / {report.analysis.recommendation.quantity}바이알</dd></div><div><dt>구매·운송 소계</dt><dd>{won(report.analysis.recommendation.subtotal)}</dd></div><div><dt>검증 총비용</dt><dd>{won(report.analysis.recommendation.total)}</dd></div><div><dt>검증 데이터</dt><dd>R{report.revision} · {report.id}</dd></div></dl><p>입고 Lot의 QC/QA는 아직 미래 예측입니다. 발주 승인이 실제 재고·사용 승인 상태를 바꾸지 않습니다.</p><div className="modal-actions"><Button variant="outline" onClick={()=>setModal(null)}>돌아가기</Button><Button disabled={approvalProblems.length>0} onClick={approve}><Check size={14}/>가상 PO 등록</Button></div></>}</Modal>
 <Modal title="분석 버전 · 근거 이력" open={modal==='history'} onClose={()=>setModal(null)} wide><p>분석 당시 원본 데이터, 결과, 실행 이벤트를 함께 보존합니다. 이전 버전을 열어도 수정된 원본으로 승인할 수 없습니다.</p><div className="erp-history-list">{reports.length?reports.map(r=><button key={r.id} onClick={()=>{setReport(r);setModal(null);go('recommendation')}}><div><Tag tone={r.fingerprint===fingerprint(data)?'green':'amber'}>R{r.revision}</Tag><b>{r.id}</b></div><p>{r.analysis.selected?`${r.analysis.selected}안 · ${won(r.analysis.recommendation!.subtotal)}`:'추천 보류'} · {r.events.length}개 실행 이벤트</p><small>{new Date(r.createdAt).toLocaleString('ko-KR')}<ArrowRight size={13}/></small></button>):<div className="erp-empty"><History size={28}/><p>분석 이력이 없습니다.</p></div>}</div></Modal>
 <Modal title="업무 데이터 초기화" open={modal==='reset'} onClose={()=>setModal(null)}><h2 className="erp-modal-h2">최초 PDF 기준 데이터로 돌아갈까요?</h2><p>직접 편집한 값, 가상 PO, 분석 스냅샷과 변경 이력을 초기화합니다. 기존 FGF-2 데모의 저장 데이터에는 영향을 주지 않습니다.</p><div className="modal-actions"><Button variant="outline" onClick={()=>setModal(null)}>돌아가기</Button><Button variant="danger" onClick={()=>{setData(createSeed());setOrders([]);setReports([]);setReport(null);setEvents([]);setRunning(false);setStarted(false);setSelectedRow(null);setSelectedEvent(null);setAnswer('');setQuestion('');setCandidate('B');setModal(null);setPage('dashboard');setToast('기준 데이터로 초기화했습니다. IL-7 장부 6개 / 생산 가용 2개')}}>전체 업무 데이터 초기화</Button></div></Modal>
 <Modal title="BioFlow 업무형 시연 안내" open={modal==='help'} onClose={()=>setModal(null)} wide><Tag tone="blue">DATA → EVIDENCE → DECISION</Tag><h2 className="erp-modal-h2">계산이 바뀌는 순간을 확인하세요.</h2><div className="guide-steps">{[['01','가용재고 확인','대시보드에서 IL-7 장부 6개와 생산 가용 2개를 비교합니다. Lot 셀을 선택해 품질 보류·만료 근거를 확인합니다.'],['02','실제 데이터 분석','Workspace 분석을 실행합니다. Lot 조회 → 제외 → 순소요 → MOQ → 총비용 → QC/QA → 최종 검증을 관찰하고 로그를 눌러 스냅샷을 확인합니다.'],['03','추천·가상 발주','B안의 구매·운송 1,230만원과 생산 후 2개 유지 조건을 확인하고 내부 가상 PO를 등록합니다.'],['04','QC 지연 적용','변형 시나리오에서 QC 병목 +3일을 선택한 뒤 재분석합니다. 2회차 사용일 11.12, PROD-02 부족, 추천 보류와 수정 조치를 확인합니다.'],['05','원본 변경과 재검증','단가·MOQ·재고·생산일·QC 대기를 편집합니다. 연결 계산이 바뀌고 이전 추천이 stale 처리되는 것을 확인합니다.']].map(([n,t,p])=><div key={n}><span>{n}</span><div><strong>{t}</strong><p>{p}</p></div></div>)}</div><div className="modal-actions"><Button onClick={()=>{setModal(null);start()}}><Play size={14}/>데이터 분석 시작</Button></div></Modal>
 <AnimatePresence>{toast&&<motion.div role="status" className="toast erp-toast" initial={{opacity:0,y:12}} animate={{opacity:1,y:0}} exit={{opacity:0,y:12}}><CheckCircle2 size={18}/>{toast}<button aria-label="알림 닫기" onClick={()=>setToast('')}><X size={14}/></button></motion.div>}</AnimatePresence>
 </div>
}
function ScheduleTable({option,data}:{option:Option;data:ErpData}){return <div className="erp-schedule-table"><div className="schedule-header"><span>입고 회차 / Lot</span><span>입고 처리</span><span>QC / QA 예상</span><span>생산 투입</span></div>{option.deliveries.map((s,i)=>{const p=data.productions[i],check=option.checks.find(x=>x.id===p?.id);return <div className={'schedule-row '+(!s.included||check?.shortage?'risk':'')} key={s.id}><div><b>{s.id} · {s.quantity}개</b><small>{s.lot}</small></div><div><span>{shortDate(s.arrival)}</span><small>{s.commitment||'미확약'}</small></div><div><span>{shortDate(s.available)}{s.qcDelay>0&&<Tag tone="red">+{s.qcDelay}일 대기</Tag>}</span><small>{s.included?'예측 · 실제 사용 승인 별도':s.reason}</small></div><div><b>{p?.id} · {p?shortDate(p.date):'—'}</b><small>{check?check.shortage?`${check.shortage}개 부족`:`투입 후 ${check.after}개`:'연결 미정'}</small></div></div>})}</div>}
function DetailBody({row,kind,data}:{row:Row;kind:TableKind;data:ErpData}){let values:Record<string,unknown>={};if(kind==='lots'){const l=data.lots.find(l=>l.id===row.id);const p=data.products.find(p=>p.id===l?.material);values={제품코드:p?.sku,제조사:p?.manufacturer,'제형 / 함량 기호':p?.form+' / '+p?.content,'보관 규격':p?.storage,'승인 근거':p?.approval,'CoA 참조':l?.coa,'온도 기록':l?.temperature,'보류 사유':l?.hold||'없음','해제 조건':l?.releaseCondition};}else if(kind==='quotes'){const v=data.vendors.find(v=>v.id===row.id);values={견적번호:v?.quoteRef,견적유효일:v?.quoteExpiry,계약근거:v?.contractRef,변경조건:v?.changeTerms,공급확약:v?.confirmed?'회차별 확약 있음':'출하·납품실적 미확인',제품승인:v?.productApproved?'승인':'미승인'};}else if(kind==='shipments'){const s=data.vendors.flatMap(v=>v.shipments).find(s=>s.id===row.id);values={Lot:s?.lot,CoA:s?.coa,확약근거:s?.commitment||'미확약',QA보류:(row.qaHold??s?.qaHold)?'보류 · 담당자 해제 필요':'미래 사용 승인 필요',온도:s?.temperature,지급일:s?.payment,현금한도:s?won(s.cashLimit):'—','영향 일치 근거':data.notices?.filter(n=>n.relevanceConfirmed&&n.lot===s?.lot).map(n=>n.id+' · '+n.manufacturer+' / '+n.product).join(' · ')||'해당 없음'};}else if(kind==='production'){values={생산번호:row.id,투입일:row.date,필요량:row.need,투입전예측:row.before,부족:row.shortage,투입후예측:row.after,원료배분:JSON.stringify(row.allocations),'고객 납기 판정':'원료 투입 충족만으로 고객 납기 확정하지 않음'};}else{values={공급안:row.id,구매운송소계:won(Number(row.subtotal)),총비용:won(Number(row.total)),예상폐기:row.waste,'폐기 장부가액 (총비용 중복 제외)':won(Number(row.wasteValue)),'필수조건 실패':Array.isArray(row.constraints)?row.constraints.join(' · '):'없음'};}return <dl className="erp-detail-dl">{Object.entries(values).map(([k,v])=><div key={k}><dt>{k}</dt><dd>{String(v??'—')}</dd></div>)}</dl>}
const orderColumns:Column[]=[{key:'id',label:'발주번호'},{key:'material',label:'원료 코드'},{key:'vendor',label:'공급업체'},{key:'quantity',label:'발주 수량',kind:'number'},{key:'subtotal',label:'구매·운송 소계',kind:'number',format:v=>won(Number(v))},{key:'total',label:'검증 총비용',kind:'number',format:v=>won(Number(v))},{key:'revision',label:'승인 revision'},{key:'status',label:'변경 검토 상태'},{key:'quality',label:'품질 사용 승인'},{key:'report',label:'분석 근거 ID'}];
function BarChartIcon(){return <Wallet size={15}/>}
